<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Holder\UserMfaRecoveryCodeCodeHashAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserMfaRecoveryCodeCodeHashAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserMfaRecoveryCodeCodeHashAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getCodeHash returns null on a freshly created holder.
     */
    public function testCodeHashNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeCodeHashAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isCodeHashAssigned());
        $this->assertNull($holder->getCodeHash());
    }
}
class ImplWithUserMfaRecoveryCodeCodeHashAttributeHolderUnitTest
{
    use UserMfaRecoveryCodeCodeHashAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedCodeHashRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultCodeHash();
    }
}
